import{_ as l,l as i,o as e,c as n,v as t,p as s,x as o,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"簿的宏观形状","description":"","frontmatter":{"title":"簿的宏观形状","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/lob-shape-macro.md","filePath":"quant/lob-shape-macro.md","lastUpdated":1789023840000}'),h={name:"quant/lob-shape-macro.md"};function u(E,a,m,B,_,q){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="簿的宏观形状" tabindex="-1">簿的宏观形状 <a class="header-anchor" href="#簿的宏观形状" aria-label="Permalink to &quot;簿的宏观形状&quot;">​</a></h1><div class="epigraph"><p>把许多微秒级的增撤成交加总，限价簿往往露出稳定的平均轮廓：近端浅、往外先增后减，或按价格距离呈幂律。形状是排队博弈的宏观结果，不是另画一张供需曲线。</p><footer>—— Bouchaud, Mézard and Potters, Statistical properties of stock order books, Quantitative Finance, 2002</footer></div><p><a href="/quant/quote-cancellation-game">上一课</a>把撤单写成缩短被捡窗口、也缩短有效在场时间；高撤单率可以是理性做市，寿命 \\(\\tau\\) 与报价联立。从 Parlour 到撤单，理论停在个体策略。缺口是加总：为什么平均深度作为价格距离的函数长得像那样，以及这个轮廓对冲击 \\(P(Q)\\) 意味着什么。本课用 Bouchaud、Mézard 与 Potters（2002）的统计形状连接微观博弈与可观测轮廓，不重推 tick 几何。不要把平均形状当成可成交路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单人最优放置给出「在哪些档有正概率挂单」，没有给出平均每档多少手。要把耐心分布、到达强度、撤单寿命与被捡放在一起，才会得到 \\(q(k)\\)——第 \\(k\\) 档平均深度。经验上许多品种近端并不最厚：BBO 更新太快、占位被速度拿走，厚度出现在几档之外；更远处挂单变成过时备忘录，又变薄。问题是哪些微观比较静态移动这个驼峰，以及沿平均形状积分得到的冲击，和瞬时可见形状上的冲击差多少。</p><p>Glosten 曲线是盈亏平衡价格表，是理论对象；宏观形状是平均量的轮廓，是统计对象。两者相关：开口陡的信息环境里，远端量更不愿意待着，轮廓更集中在近端或更空。</p><h3 id="不要把平均形状当成可成交路径" tabindex="-1">不要把平均形状当成可成交路径 <a class="header-anchor" href="#不要把平均形状当成可成交路径" aria-label="Permalink to &quot;不要把平均形状当成可成交路径&quot;">​</a></h3><p>平均 \\(q(k)\\) 对时间积分。你下市价单的那一瞬间，形状是随机的，近端可能被撤空。沿平均轮廓算 \\(P(Q)\\) 会低估尾部冲击。宏观形状适合比较品种、比较 tick 制度、比较是否 pro-rata，不适合做单笔执行的确定性轨迹。</p><p><span class="marginnote">Bouchaud 等人还报告价格距离上的幂律与反相关的订单流。本课只取「平均轮廓」这一层；流的自相关属于执行与 Hawkes 课，不在这里展开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每个价位相对中点的距离 \\(\\delta\\)（以 tick 计）估计 \\(E[q\\mid\\delta]\\)，分买卖、分时段。比较：tick 变细时轮廓在 \\(\\delta\\) 上被打散；FIFO 对 pro-rata 时近端峰值不同；开盘事件不确定高时近端更空。把微观理论当预测：被捡升 → 近端寿命短 → 平均近端更薄；非执行升（收盘）→ 近端变厚。</p><p>冲击：随机形状上吃 \\(Q\\) 的期望均价，对形状分布积分。这比 Glosten 确定性曲线多一层方差：同样的 \\(E[q(\\delta)]\\)，若形状波动大，大单冲击的凸性更强（Jensen）。执行应关心形状的波动，不只关心均值。</p><h3 id="从-rosu-排序到轮廓" tabindex="-1">从 Roşu 排序到轮廓 <a class="header-anchor" href="#从-rosu-排序到轮廓" aria-label="Permalink to &quot;从 Roşu 排序到轮廓&quot;">​</a></h3><p>若耐心连续分布，Roşu 预言更有耐心的量更远。把分布积分，得到单调向外堆积的形状——这常被近端速度效应修正：最急的做市商用短寿命占 BBO，平均量却不大，于是驼峰出现在「次急且愿意待着」的档。宏观形状因此是耐心 × 寿命的结果，不是单一参数。</p>',14)),(e(),s(c,null,{default:o(()=>[p(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20LR%0A%20%20Micro%5B%22%E6%94%BE%E7%BD%AE%20%2F%20%E6%92%A4%E5%8D%95%20%2F%20%E4%BC%98%E5%85%88%E8%A7%84%E5%88%99%22%5D%20--%3E%20Shape%5B%22%E5%B9%B3%E5%9D%87%20q(%CE%B4)%22%5D%0A%20%20Shape%20--%3E%20MeanP%5B%22%E6%B2%BF%E5%9D%87%E5%80%BC%E7%9A%84%E5%86%B2%E5%87%BB%22%5D%0A%20%20Var%5B%22%E5%BD%A2%E7%8A%B6%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20Conv%5B%22%E5%A4%A7%E5%8D%95%E5%86%B2%E5%87%BB%E5%87%B8%E6%80%A7%22%5D%0A%20%20MeanP%20--%3E%20Conv%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>轮廓是流动性供给的直方图。政策改优先规则或 tick，直方图重塑，再进入冲击与价差。这是市场设计影响执行成本的通道，不必经过「投资者情绪」。信息体制切换（Easley–O&#39;Hara 有事件日）会把直方图压扁：人们不愿在任何 \\(\\delta\\) 上久留。库存压力把直方图左右平移，像 Ho–Stoll 偏度的加总版。</p><p>与 Kyle 对照：线性 \\(\\lambda\\) 相当于假定形状给出常斜率。宏观形状开口则给出非线性 \\(P(Q)\\)，大单更贵。经验 Kyle 回归只在小 \\(Q\\) 上局部有效，与 Glosten 近端近似同一句话。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>幂律拟合对样本与截断敏感，不要发明普适指数。不同资产类别形状不可比：外汇 ECN、国债期货 pro-rata、美股 FIFO 是三种直方图。隐藏量使可见轮廓系统性偏薄。均场课下一步才问轮廓是否作为偏微分方程的稳态出现。</p><p><span class="marginnote">把平均簿画成供需曲线并读「均衡价格」，是范畴错误：那是已提交指令的直方图，意愿会随价格移动一起撤走。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>宏观形状是微观放置、寿命与优先规则的平均轮廓，常呈近端浅、中距厚、远端再薄。</li><li>沿平均形状算冲击会忽略形状波动带来的凸性。</li><li>轮廓随 tick、规则、事件不确定移动，是设计影响成本的通道。</li><li>出处：Bouchaud, Mézard and Potters, <em>Quantitative Finance</em>, 2002；微观基础见 Parlour、Roşu 与 Foucault 等。</li></ul>',8))])}const b=l(h,[["render",u]]);export{P as __pageData,b as default};
